import { describe, expect, it, vi, beforeEach, afterEach } from "vitest";
import { loadConfig, ConfigError } from "@/lib/config";
import { hashPassword, verifyPassword } from "@/lib/passwords";
import * as paths from "@/lib/paths";
import { ApiError } from "@/lib/errors";
import { GitHubStorage, MemoryStorage, Conflict, Busy, TooLarge, Upstream, blobSha } from "@/lib/storage";
import { RateLimiter } from "@/lib/ratelimit";
import { encodeSession, decodeSession } from "@/lib/session";
import { TEST_ENV } from "./helpers";

// Reference hashes generated by the Python werkzeug library used by the earlier Flask version.
const WERKZEUG_SCRYPT = "scrypt:32768:8:1$P9HwgZ7Kfav4CLNo$93171ff6a7ba8f096dbbb9dfbabb03bdea104fabebfc7752876dae184e8a62dd3fa6013e3ccdfe0a824df58f79cb9db23e983bd8dd9b3e6fb4bce4a7f9b6fcf8";
const WERKZEUG_PBKDF2 = "pbkdf2:sha256:600000$BiFw2ef11ss1Au0E$e2d05b3d22f335fb33f126b007839c4ffd0ec7a5e3fef24ef5e0abc06e1f2088";

describe("config", () => {
  it("accepts a complete environment and applies defaults", () => {
    const cfg = loadConfig(TEST_ENV);
    expect(cfg.sessionHours).toBe(12);
    expect(cfg.maxRecordBytes).toBe(64 * 1024);
    expect(cfg.maxFileBytes).toBe(1_000_000);
    expect(cfg.corsAllowedOrigins).toEqual(["https://app.example.com"]);
  });

  it("names missing variables but never prints their values", () => {
    const env = { ...TEST_ENV, GITHUB_TOKEN: "", API_KEY_HASH_SECRET: undefined };
    try {
      loadConfig(env);
      throw new Error("expected ConfigError");
    } catch (e) {
      expect(e).toBeInstanceOf(ConfigError);
      const msg = (e as Error).message;
      expect(msg).toContain("GITHUB_TOKEN");
      expect(msg).toContain("API_KEY_HASH_SECRET");
      expect(msg).not.toContain(TEST_ENV.SECRET_KEY);
      expect(msg).not.toContain(TEST_ENV.API_KEY_HASH_SECRET);
    }
  });

  it("rejects wildcard and non-https CORS origins", () => {
    expect(() => loadConfig({ ...TEST_ENV, CORS_ALLOWED_ORIGINS: "*" })).toThrow(/Wildcard/);
    expect(() => loadConfig({ ...TEST_ENV, CORS_ALLOWED_ORIGINS: "http://evil.example.com" })).toThrow(/https/);
  });

  it("allows localhost origins for development", () => {
    expect(loadConfig({ ...TEST_ENV, CORS_ALLOWED_ORIGINS: "http://localhost:3000/" }).corsAllowedOrigins).toEqual([
      "http://localhost:3000",
    ]);
  });

  it("rejects SameSite=None without secure cookies and malformed repo names", () => {
    expect(() => loadConfig({ ...TEST_ENV, COOKIE_SAMESITE: "None" })).toThrow(/requires secure/);
    expect(() => loadConfig({ ...TEST_ENV, PRIVATE_DATA_REPO: "not a repo" })).toThrow(/owner\/name/);
  });

  it("clamps the file limit to the Contents API maximum", () => {
    expect(loadConfig({ ...TEST_ENV, MAX_FILE_BYTES: "5000000" }).maxFileBytes).toBe(1_000_000);
  });
});

describe("passwords", () => {
  it("round-trips with the current scrypt format", () => {
    const h = hashPassword("a-good-password");
    expect(h.startsWith("scrypt:32768:8:1$")).toBe(true);
    expect(verifyPassword(h, "a-good-password")).toBe(true);
    expect(verifyPassword(h, "a-wrong-password")).toBe(false);
  });

  it("verifies hashes created by the earlier Python (werkzeug) version", () => {
    expect(verifyPassword(WERKZEUG_SCRYPT, "correct horse battery")).toBe(true);
    expect(verifyPassword(WERKZEUG_SCRYPT, "wrong")).toBe(false);
    expect(verifyPassword(WERKZEUG_PBKDF2, "pw-pbkdf2")).toBe(true);
    expect(verifyPassword(WERKZEUG_PBKDF2, "pw-pbkdf2 ")).toBe(false);
  });

  it("rejects malformed or unknown hash formats", () => {
    expect(verifyPassword("md5$salt$abc", "x")).toBe(false);
    expect(verifyPassword("garbage", "x")).toBe(false);
  });
});

describe("paths and validation", () => {
  it("accepts well-formed app ids and rejects traversal", () => {
    expect(paths.appId("my-app-1a2b3c")).toBe("my-app-1a2b3c");
    for (const bad of ["../x", "A", "1abc", "a/b", "ab", "x".repeat(41)]) {
      expect(() => paths.appId(bad)).toThrow(ApiError);
    }
  });

  it("validates collections, usernames, and record ids", () => {
    expect(() => paths.collection("notes")).not.toThrow();
    expect(() => paths.collection("Bad Name")).toThrow(/Invalid collection/);
    expect(() => paths.username("ab")).toThrow(/Username/);
    expect(() => paths.recordId("../../etc")).toThrow(ApiError);
  });

  it("reduces client filenames to a safe display name", () => {
    expect(paths.safeFilename("../../etc/passwd")).toBe("passwd");
    expect(paths.safeFilename("..\\..\\win.ini")).toBe("win.ini");
    expect(paths.safeFilename("")).toBe("file");
    expect(paths.safeFilename("a<b>.txt")).toBe("file");
    expect(paths.safeFilename("report 2026.pdf")).toBe("report 2026.pdf");
  });
});

describe("sessions", () => {
  it("accepts a correctly signed cookie and rejects a tampered one", () => {
    const secret = "k".repeat(32);
    const value = encodeSession({ uid: "abc", iat: 1, csrf: "t" }, secret);
    expect(decodeSession(value, secret)).toEqual({ uid: "abc", iat: 1, csrf: "t" });
    const forged = value.replace(/^./, (c) => (c === "e" ? "f" : "e"));
    expect(decodeSession(forged, secret)).toEqual({});
    expect(decodeSession(value, "other-secret-0000000000000000")).toEqual({});
  });
});

describe("rate limiter", () => {
  it("allows up to the limit inside the window", () => {
    const rl = new RateLimiter();
    expect(rl.allow("k", 2, 60)).toBe(true);
    expect(rl.allow("k", 2, 60)).toBe(true);
    expect(rl.allow("k", 2, 60)).toBe(false);
    rl.clear("k");
    expect(rl.allow("k", 2, 60)).toBe(true);
  });
});

describe("MemoryStorage", () => {
  it("refuses to overwrite on create and refuses stale updates", async () => {
    const s = new MemoryStorage();
    const sha1 = await s.write("a/b.json", Buffer.from("1"), "create");
    expect(sha1).toBe(blobSha(Buffer.from("1")));
    await expect(s.write("a/b.json", Buffer.from("2"), "create")).rejects.toBeInstanceOf(Conflict);
    await expect(s.write("a/b.json", Buffer.from("2"), "update", "stale")).rejects.toBeInstanceOf(Conflict);
    const sha2 = await s.write("a/b.json", Buffer.from("2"), "update", sha1);
    await expect(s.delete("a/b.json", sha1, "stale delete")).rejects.toBeInstanceOf(Conflict);
    expect(await s.delete("a/b.json", sha2, "delete")).toBe(true);
  });

  it("lists only direct children", async () => {
    const s = new MemoryStorage();
    await s.write("d/x.json", Buffer.from("1"), "m");
    await s.write("d/y.json", Buffer.from("1"), "m");
    await s.write("d/sub/z.json", Buffer.from("1"), "m");
    expect((await s.list("d")).map((e) => e.name)).toEqual(["x.json", "y.json"]);
  });
});

describe("GitHubStorage (mocked GitHub)", () => {
  const realFetch = globalThis.fetch;
  let calls: Array<{ url: string; method: string }>;

  function mockFetch(responses: Array<() => Response>) {
    calls = [];
    let i = 0;
    globalThis.fetch = (async (url: string, init: RequestInit) => {
      calls.push({ url: String(url), method: init.method ?? "GET" });
      const make = responses[Math.min(i, responses.length - 1)];
      i++;
      return make();
    }) as typeof fetch;
  }

  beforeEach(() => {
    calls = [];
  });
  afterEach(() => {
    globalThis.fetch = realFetch;
    vi.restoreAllMocks();
  });

  const json = (status: number, body: unknown, headers: Record<string, string> = {}) =>
    () => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", ...headers } });

  it("reads and decodes file content with its sha", async () => {
    mockFetch([json(200, { type: "file", encoding: "base64", size: 2, content: Buffer.from("hi").toString("base64"), sha: "abc" })]);
    const s = new GitHubStorage("tok", "owner/repo");
    const got = await s.read("users/x.json");
    expect(got?.data.toString()).toBe("hi");
    expect(got?.sha).toBe("abc");
    expect(calls[0].url).toBe("https://api.github.com/repos/owner/repo/contents/users/x.json");
  });

  it("returns null for missing files", async () => {
    mockFetch([json(404, { message: "Not Found" })]);
    expect(await new GitHubStorage("tok", "owner/repo").read("nope.json")).toBeNull();
  });

  it("never retries a write, so a 5xx cannot overwrite a newer change", async () => {
    mockFetch([json(500, { message: "boom" })]);
    await expect(new GitHubStorage("tok", "owner/repo").write("a.json", Buffer.from("x"), "m", "sha1")).rejects.toBeInstanceOf(Upstream);
    expect(calls.filter((c) => c.method === "PUT")).toHaveLength(1);
  });

  it("maps a stale-sha write rejection to Conflict (409) without retrying", async () => {
    mockFetch([json(409, { message: "sha does not match" })]);
    await expect(new GitHubStorage("tok", "owner/repo").write("a.json", Buffer.from("x"), "m", "old")).rejects.toBeInstanceOf(Conflict);
    expect(calls).toHaveLength(1);
  });

  it("retries transient read errors a bounded number of times", async () => {
    vi.spyOn(globalThis, "setTimeout").mockImplementation(((fn: () => void) => { fn(); return 0 as any; }) as any);
    mockFetch([json(500, {}), json(200, { type: "file", encoding: "base64", content: "", size: 0, sha: "s" })]);
    const got = await new GitHubStorage("tok", "owner/repo").read("a.json");
    expect(got?.sha).toBe("s");
    expect(calls).toHaveLength(2);
  });

  it("reports rate limits as Busy (429)", async () => {
    mockFetch([json(403, { message: "rate limit" }, { "x-ratelimit-remaining": "0" })]);
    await expect(new GitHubStorage("tok", "owner/repo").read("a.json")).rejects.toBeInstanceOf(Busy);
  });

  it("refuses content the Contents API did not return", async () => {
    mockFetch([json(200, { type: "file", encoding: "none", size: 2_000_000, content: "", sha: "s" })]);
    await expect(new GitHubStorage("tok", "owner/repo").read("big.bin")).rejects.toBeInstanceOf(TooLarge);
  });

  it("never includes the token in thrown errors", async () => {
    mockFetch([json(500, { message: "x" })]);
    try {
      await new GitHubStorage("ghp_secret_value_123", "owner/repo").write("a.json", Buffer.from("x"), "m");
    } catch (e) {
      expect(String((e as Error).message)).not.toContain("ghp_secret_value_123");
    }
  });
});
